INSERT INTO `blogs` (`id`, `title`, `content`, `img`, `user_id`, `group_id`, `category_id`, `file_type`, `created_at`, `updated_at`) VALUES
(37, 'سلام', '<p>سلام و تیت</p>', '1752952875.png', 208, 5012, 15, 'image/png', '2025-07-19 22:51:15', '2025-07-19 22:51:15'),
(39, 'لورم ایپسوم متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ', '<p>لورم ایپسوم متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ، و با استفاده از طراحان گرافیک است، چاپگرها و متون بلکه روزنامه و مجله در ستون و سطرآنچنان که لازم است، و برای شرایط فعلی تکنولوژی مورد نیاز، و کاربردهای متنوع با هدف بهبود ابزارهای کاربردی می باشد، کتابهای زیادی در شصت و سه درصد گذشته حال و آینده، شناخت فراوان جامعه و متخصصان را می طلبد، تا با نرم افزارها شناخت بیشتری را برای طراحان رایانه ای علی الخصوص طراحان خلاقی، و فرهنگ پیشرو در زبان فارسی ایجاد کرد، در این صورت می توان امید داشت که تمام و دشواری موجود در ارائه راهکارها، و شرایط سخت تایپ به پایان رسد و زمان مورد نیاز شامل حروفچینی دستاوردهای اصلی، و جوابگوی سوالات پیوسته اهل دنیای موجود طراحی اساسا مورد استفاده قرار گیرد.</p>', '1754832207.png', 213, 6071, 13, 'image/png', '2025-08-10 16:53:27', '2025-08-10 16:53:27'),
(40, 'jsjjhg', '<p>jhg rddr 86ttu66r5e lihhuyygtd jygjv&nbsp; &nbsp;ytfrsex</p>', '1754833816.jpg', 217, 6071, 14, 'image/jpeg', '2025-08-10 17:20:16', '2025-08-10 17:20:16'),
(41, 'تست', '<p>تست تست</p>', '1754942817.jpeg', 223, 6071, 12, 'image/jpeg', '2025-08-11 23:36:57', '2025-08-11 23:36:57'),
(42, 'آزمایش', 'برای سنجاق کردن کلیپ، آن را لمس کنید و نگه دارید. کلیپ‌هایی که سنجاق از آن‌ها برداشته می‌شود، پس‌از ۱ ساعت حذف می‌شوند.', '1755953502.jpg', 222, 6071, 12, 'image/jpeg', '2025-08-13 20:51:08', '2025-08-29 16:11:22'),
(43, 'پیشنهاد احداث نیروگاه خورشیدی', 'با سلام، پیشنهاد میکنم با توجه به ناپایداری وضع برق برای محله ی تجریش یک نیروگاه خورشیدی متمرکز یا منتشر احداث کنیم.', NULL, 222, 6071, 12, NULL, '2025-08-14 18:34:57', '2025-08-29 16:06:37'),
(44, 'سلام پیشنهاد تغییر فونت', '<p>سلام پیشنهاد تغییر فونت</p>', NULL, 224, 6072, 12, NULL, '2025-08-14 18:36:26', '2025-08-14 18:36:26'),
(46, 'پیشنهاد پروژه 1', '<p>پیشنهاد&nbsp;</p>\nدلرم', '1757082521.png', 222, 6071, 15, 'image/png', '2025-09-05 17:58:41', '2025-09-05 18:17:30'),
(47, 'تست', '<p>تست</p>', NULL, 222, 6079, 16, NULL, '2025-09-08 00:06:26', '2025-09-08 00:06:26'),
(48, 'تست', '<p>تست</p>', NULL, 222, 6074, 16, NULL, '2025-09-08 00:07:21', '2025-09-08 00:07:21'),
(49, 'گزارش افتتاحیه گروه', '<p>به گروه محله خود خوش آمدید</p>', '1764692245.png', 5, 25, 12, 'image/png', '2025-12-02 19:47:25', '2025-12-02 19:47:25'),
(50, 'تست', '<p>الللبفیق&nbsp; 4یتغ اامناعغیلیسیق لالغیفیسبطز</p>', NULL, 5, 25, 13, NULL, '2026-01-02 23:33:56', '2026-01-02 23:33:56');
