INSERT INTO `blog_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `category_id`, `user_id`, `status`, `published_at`, `views_count`, `is_featured`, `allow_comments`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'چرا همکاری جهانی تنها راه مهار بحران اقلیمی است؟', 'global-cooperation-for-climate', 'از پیمان پاریس تا ابتکارات محلی؛ چرا بدون اقدام جمعی، هیچ کشوری از پیامدهای گرمایش جهانی در امان نیست.', '<h2>مقدمه</h2><p>گرمایش جهانی مرز نمی‌شناسد و آلودگی کربن هر کشوری، گریبان همه را می‌گیرد.</p><h2>نکات کلیدی</h2><ul><li>عدالت اقلیمی: کشورهای کم‌انتشار بیشترین آسیب را می‌بینند.</li><li>استانداردهای مشترک: گزارش‌دهی شفاف، قیمت‌گذاری کربن و ردیابی زنجیره تأمین.</li><li>دیپلماسی شهری: شبکه شهرهای C40 نشان داده همکاری شهری می‌تواند از دولت‌ها جلو بزند.</li></ul><h2>گام‌های عملی</h2><ul><li>پیوند پروژه‌های محلی به اهداف SDG.</li><li>ایجاد صندوق‌های مشترک کاهش کربن در سطح منطقه‌ای.</li><li>اشتراک داده و فناوری متن‌باز برای پایش آلاینده‌ها.</li></ul>', NULL, 5, 5, 'published', '2026-01-04 11:37:40', 509, 1, 1, 'چرا همکاری جهانی تنها راه مهار بحران اقلیمی است؟', 'از پیمان پاریس تا ابتکارات محلی؛ چرا بدون اقدام جمعی، هیچ کشوری از پیامدهای گرمایش جهانی در امان نیست.', 'climate-action,global-collaboration,collective-action', '2026-01-05 11:37:40', '2026-01-05 11:45:05', NULL),
(2, 'انرژی‌های تجدیدپذیر 2030: خورشیدی، بادی و ذخیره‌سازی هوشمند', 'renewables-2030', 'ترکیب فتوولتائیک، توربین‌های بادی ساحلی و باتری‌های شبکه چگونه هزینه انرژی پاک را می‌شکند.', '<h2>وضعیت بازار</h2><p>هزینه هر کیلووات‌ساعت خورشیدی در ۱۰ سال ۸۰٪ کاهش یافته است.</p><h2>فناوری‌های کلیدی</h2><ul><li>PV پربازده با سلول‌های پرواسکایت.</li><li>باد ساحلی و توربین‌های شناور برای اعماق بیشتر.</li><li>ذخیره‌سازی: باتری LFP، هیدروژن سبز و ذخیره‌سازی گرمایی.</li></ul><h2>مدل‌های تعاونی</h2><ul><li>نیروگاه خورشیدی اشتراکی برای محلات.</li><li>تأمین مالی جمعی توربین بادی محلی.</li><li>قرارداد خرید انرژی (PPA) جمعی برای کسب‌وکارهای کوچک.</li></ul>', NULL, 6, 5, 'published', '2026-01-03 11:37:41', 309, 1, 1, 'انرژی‌های تجدیدپذیر 2030: خورشیدی، بادی و ذخیره‌سازی هوشمند', 'ترکیب فتوولتائیک، توربین‌های بادی ساحلی و باتری‌های شبکه چگونه هزینه انرژی پاک را می‌شکند.', 'clean-energy,collective-action,open-tech', '2026-01-05 11:37:41', '2026-01-05 11:37:41', NULL),
(3, 'اقتصاد چرخشی و صفرزباله: از طراحی تا اجرا', 'circular-zero-waste', 'چگونه با طراحی چرخه‌گرا، جریان مواد را می‌بندیم و هزینه دفن را به سرمایه اجتماعی تبدیل می‌کنیم.', '<h2>چارچوب</h2><p>طراحی برای جداسازی، استفاده مجدد و بازیافت از ابتدای زنجیره.</p><h2>نمونه‌ها</h2><ul><li>مدل ودیعه‌گذاری بسته‌بندی در خرده‌فروشی محلی.</li><li>کارگاه‌های تعمیر جمعی (Repair Café) برای لوازم خانگی.</li><li>تفکیک در مبدأ با انگیزه اقتصادی به شکل کوین محلی.</li></ul><h2>شاخص‌ها</h2><ul><li>کاهش پسماند سرانه</li><li>نرخ بازیافت مواد بحرانی (لیتیوم، مس، آلومینیوم)</li><li>کاهش انتشار ناشی از دفن</li></ul>', NULL, 8, 5, 'published', '2026-01-02 11:37:41', 811, 0, 1, 'اقتصاد چرخشی و صفرزباله: از طراحی تا اجرا', 'چگونه با طراحی چرخه‌گرا، جریان مواد را می‌بندیم و هزینه دفن را به سرمایه اجتماعی تبدیل می‌کنیم.', 'circular-economy,collective-action', '2026-01-05 11:37:41', '2026-01-05 11:37:41', NULL),
(4, 'شهرهای تاب‌آور: نقش همکاری شهروندی در تاب‌آوری آب‌وهوایی', 'resilient-cities-cooperation', 'از باغ‌های بارانی تا هشدار سیل محلی؛ مشارکت مردم چگونه زیرساخت خاکستری را تکمیل می‌کند.', '<h2>چالش</h2><p>افزایش سیلاب‌های ناگهانی و موج‌های گرما در شهرها.</p><h2>راهکارهای مردم‌بنیان</h2><ul><li>باغچه‌های بارانی و سطوح نفوذپذیر با مالکیت جمعی.</li><li>شبکه داوطلبان هشدار سیل با سنسورهای ارزان و متن‌باز.</li><li>سایه‌بان‌های شهری و خنک‌سازی طبیعت‌محور با مشارکت محلی.</li></ul><h2>حاکمیت</h2><p>بودجه‌ریزی مشارکتی برای پروژه‌های تاب‌آوری محله.</p>', NULL, 7, 5, 'published', '2026-01-01 11:37:41', 283, 0, 1, 'شهرهای تاب‌آور: نقش همکاری شهروندی در تاب‌آوری آب‌وهوایی', 'از باغ‌های بارانی تا هشدار سیل محلی؛ مشارکت مردم چگونه زیرساخت خاکستری را تکمیل می‌کند.', 'resilient-cities,collective-action,global-collaboration', '2026-01-05 11:37:41', '2026-01-05 11:37:41', NULL),
(5, 'کشاورزی احیاگر تعاونی: خاک سالم، غذای سالم', 'regenerative-coops', 'تعاونی‌های کشاورزی چگونه با کشت پوششی، تناوب و مدیریت آب، هم پایداری و هم سود را بالا می‌برند.', '<h2>اصول</h2><ul><li>کاهش شخم و حفظ پوشش گیاهی</li><li>تناوب و کشت میان‌بَری برای بازگرداندن مواد آلی</li><li>مدیریت آب و کانتوربندی برای جلوگیری از فرسایش</li></ul><h2>مدل تعاونی</h2><p>اشتراک ادوات، خرید نهاده پایدار و فروش مشترک با برند تعاونی.</p><h2>شاخص اثر</h2><p>افزایش کربن آلی خاک و کاهش ورودی شیمیایی.</p>', NULL, 9, 5, 'published', '2025-12-31 11:37:41', 238, 0, 1, 'کشاورزی احیاگر تعاونی: خاک سالم، غذای سالم', 'تعاونی‌های کشاورزی چگونه با کشت پوششی، تناوب و مدیریت آب، هم پایداری و هم سود را بالا می‌برند.', 'regenerative-agriculture,water-management,success-cases', '2026-01-05 11:37:41', '2026-01-05 11:37:41', NULL),
(6, 'نمونه‌های موفق همکاری در بحران: از کووید تا سیل', 'cooperation-in-crisis', 'چهار مطالعه موردی از همیاری جوامع در بحران که نشان می‌دهد شبکه‌های محلی می‌توانند سریع‌تر از سیستم‌های متمرکز عمل کنند.', '<h2>مطالعه موردی ۱</h2><p>توزیع غذای تعاونی در دوران قرنطینه با اپلیکیشن محلی.</p><h2>مطالعه موردی ۲</h2><p>نقشه‌برداری مردمی از نیازهای سیل‌زدگان و تخصیص منابع.</p><h2>مطالعه موردی ۳</h2><p>تولید ماسک و تجهیزات محافظتی توسط تعاونی‌های زنان.</p><h2>درس‌آموخته</h2><p>زیرساخت دیجیتال محلی + اعتماد اجتماعی = واکنش سریع.</p>', NULL, 9, 5, 'published', '2025-12-30 11:37:41', 594, 1, 1, 'نمونه‌های موفق همکاری در بحران: از کووید تا سیل', 'چهار مطالعه موردی از همیاری جوامع در بحران که نشان می‌دهد شبکه‌های محلی می‌توانند سریع‌تر از سیستم‌های متمرکز عمل کنند.', 'success-cases,collective-action,global-collaboration', '2026-01-05 11:37:41', '2026-01-05 11:37:41', NULL),
(7, 'فناوری باز برای پایداری: سنسورها، داده و شفافیت', 'open-tech-for-sustainability', 'چگونه سخت‌افزار و نرم‌افزار متن‌باز هزینه پایش محیط زیست را کاهش می‌دهد و اعتماد عمومی می‌سازد.', '<h2>ابزارها</h2><ul><li>سنسورهای کیفیت هوا کم‌هزینه با کالیبراسیون جمعی.</li><li>داشبورد متن‌باز برای پایش کربن و مصرف انرژی.</li><li>بلاکچین سبک برای ردیابی زنجیره تأمین سبز.</li></ul><h2>حکمرانی داده</h2><p>داده باز، حریم خصوصی و مجوزهای مشارکتی.</p><h2>نمونه</h2><p>پلتفرم‌های شهروند-دانشمند در اروپا و آسیا.</p>', NULL, 7, 5, 'published', '2025-12-29 11:37:41', 229, 0, 1, 'فناوری باز برای پایداری: سنسورها، داده و شفافیت', 'چگونه سخت‌افزار و نرم‌افزار متن‌باز هزینه پایش محیط زیست را کاهش می‌دهد و اعتماد عمومی می‌سازد.', 'open-tech,clean-energy,collective-action', '2026-01-05 11:37:41', '2026-01-05 11:37:41', NULL),
(8, 'مدیریت مشارکتی آب: از حوضه تا مزرعه', 'collaborative-water-management', 'مدل‌های همیاری برای احیای سفره‌های آب زیرزمینی، تقسیم منصفانه و سازگاری با خشکسالی.', '<h2>چالش</h2><p>افت سفره‌های آب و رقابت بخشی.</p><h2>راهکار مشارکتی</h2><ul><li>بودجه‌ریزی مشترک برای قنات و آبخوان‌داری.</li><li>سهمیه‌بندی شفاف با کنتور هوشمند و داده باز.</li><li>توافقات محلی برای الگوی کشت کم‌آب‌بر.</li></ul><h2>نمونه</h2><p>تجربه حوضه گاوخونی و تعاونی‌های آب‌رسانی روستایی.</p>', NULL, 5, 5, 'published', '2025-12-28 11:37:41', 787, 0, 1, 'مدیریت مشارکتی آب: از حوضه تا مزرعه', 'مدل‌های همیاری برای احیای سفره‌های آب زیرزمینی، تقسیم منصفانه و سازگاری با خشکسالی.', 'water-management,collective-action,success-cases', '2026-01-05 11:37:41', '2026-01-05 11:37:41', NULL),
(9, 'اقتصاد تعاونی برای خنثی‌سازی کربن محلی', 'cooperative-carbon-neutrality', 'چگونه یک تعاونی محلی می‌تواند پورتفوی کربن خود را با درختکاری، بهینه‌سازی انرژی و خرید اعتبار مدیریت کند.', '<h2>گام‌ها</h2><ul><li>حسابرسی کربن داوطلبانه در سطح محله.</li><li>بسته اقدام: عایق‌کاری، به‌روزرسانی روشنایی، نصب خورشیدی اشتراکی.</li><li>پروژه‌های جذب کربن محلی (درختکاری بومی، کشاورزی احیاگر).</li></ul><h2>تأمین مالی</h2><p>صندوق محلی + کوین داخلی بهار برای تشویق مشارکت.</p><h2>سنجش</h2><p>داشبورد شفاف برای ردیابی کاهش و جبران.</p>', NULL, 6, 5, 'published', '2025-12-27 11:37:41', 339, 0, 1, 'اقتصاد تعاونی برای خنثی‌سازی کربن محلی', 'چگونه یک تعاونی محلی می‌تواند پورتفوی کربن خود را با درختکاری، بهینه‌سازی انرژی و خرید اعتبار مدیریت کند.', 'climate-action,clean-energy,collective-action', '2026-01-05 11:37:41', '2026-01-05 11:37:41', NULL),
(10, 'برنامه ۱۰۰ روزه اقدام اقلیمی برای اعضای EarthCoop', '100-day-climate-action', 'یک نقشه راه عملی برای اعضا: از ممیزی خانگی تا پیوستن به پروژه‌های جمعی و دعوت دوستان.', '<h2>هفته ۱-۲</h2><p>ممیزی انرژی و آب در منزل؛ ثبت داده در پروفایل.</p><h2>هفته ۳-۴</h2><p>پیوستن به یک گروه محلی و یک پروژه انرژی یا پسماند.</p><h2>هفته ۵-۸</h2><p>مشارکت در انتخابات/نظرسنجی مربوط به بودجه پایداری محلی.</p><h2>هفته ۹-12</h2><p>دعوت حداقل ۳ نفر، اشتراک تجربه و انتشار داستان در وبلاگ.</p><h2>شاخص موفقیت</h2><p>کاهش مصرف، مشارکت در رأی‌گیری و افزایش اعضای فعال.</p>', NULL, 5, 5, 'published', '2025-12-26 11:37:41', 336, 1, 1, 'برنامه ۱۰۰ روزه اقدام اقلیمی برای اعضای EarthCoop', 'یک نقشه راه عملی برای اعضا: از ممیزی خانگی تا پیوستن به پروژه‌های جمعی و دعوت دوستان.', 'collective-action,climate-action,invitation', '2026-01-05 11:37:41', '2026-01-05 11:37:41', NULL);
